/** Headcount of active members, including viewers, who do not occupy a seat. */
export async function countActiveMembers(orgId: OrgId): Promise<number> {
  return countMembers(orgId, false);
}

/** Active members on a billable role. This is the stored seat counter's source. */
export async function countBillableActiveMembers(orgId: OrgId): Promise<number> {
  return countMembers(orgId, true);
}

async function countMembers(
  orgId: OrgId,
  billableOnly: boolean,
): Promise<number> {
  const row = getDb()
    .select({ value: count() })
    .from(members)
    .where(
      and(
        orgPredicate(members.orgId, orgId),
        eq(members.status, "active"),
        billableOnly ? inArray(members.role, [...BILLABLE_ROLES]) : undefined,
        liveMemberPredicate(),
      ),
    )
    .get();
  return row?.value ?? 0;
}

