export async function countPendingInvitations(orgId: OrgId): Promise<number> {
  return countPending(orgId, false);
}

/** Pending invites that reserve a seat. Accepted and revoked rows are excluded. */
export async function countPendingBillableInvitations(
  orgId: OrgId,
): Promise<number> {
  return countPending(orgId, true);
}

async function countPending(
  orgId: OrgId,
  billableOnly: boolean,
): Promise<number> {
  const row = getDb()
    .select({ value: count() })
    .from(invitations)
    .where(
      and(
        orgPredicate(invitations.orgId, orgId),
        isNull(invitations.acceptedAt),
        isNull(invitations.revokedAt),
        billableOnly ? inArray(invitations.role, [...BILLABLE_ROLES]) : undefined,
      ),
    )
    .get();
  return row?.value ?? 0;
}

