/**
 * Seats occupied for an invite or a promotion: billable active members plus
 * pending invitations for a billable role. Viewer invites reserve nothing.
 * The stored `seatsUsed` counter is the member half of this only.
 */
export async function countSeatsInUse(orgId: OrgId): Promise<number> {
  const [membersInSeats, pendingInvites] = await Promise.all([
    memberRepo.countBillableActiveMembers(orgId),
    invitationRepo.countPendingBillableInvitations(orgId),
  ]);
  return membersInSeats + pendingInvites;
}

/** How many seats a role transition adds. Zero when neither side is free-only. */
function seatDelta(from: Role, to: Role): number {
  return (isBillableRole(to) ? 1 : 0) - (isBillableRole(from) ? 1 : 0);
}

/**
 * Every event that changes a counted resource nudges the cache. The deltas are
 * cheap; the periodic rollup is what corrects any drift they accumulate.
 * Seat deltas count billable active members only, matching a full recount.
 */
export function registerUsageListeners(): Unsubscribe {
  const offs: Unsubscribe[] = [
    subscribe("issue.created", async (payload) => {
      await usageRepo.incrementUsage(payload.orgId, { issuesUsed: 1 });
    }),
    subscribe("issue.archived", async (payload) => {
      await usageRepo.incrementUsage(payload.orgId, { issuesUsed: -1 });
