  // Promoting a viewer onto a full plan takes a seat and must change nothing.
  it("refuses to promote a viewer when no billable seat remains", async () => {
    const tenant = await createTenant("member-seat-promote", "free");
    const target = await memberRepo.findMember(tenant.org.id, tenant.userIds.viewer);
    if (!target) throw new Error("fixture viewer missing");

    await expect(
      memberService.updateMemberRole(tenant.actors.owner, {
        orgId: tenant.org.id,
        memberId: target.id,
        role: "member",
      }),
    ).rejects.toThrow(/seats/);

    const after = await memberRepo.findMember(tenant.org.id, tenant.userIds.viewer);
    expect(after?.role).toBe("viewer");
  });

  // Billable-to-billable and any demotion to viewer ignore the seat quota.
  it("allows role changes that do not take a seat when the plan is full", async () => {
    const tenant = await createTenant("member-seat-free-change", "free");
    const admin = await memberRepo.findMember(tenant.org.id, tenant.userIds.admin);
    const member = await memberRepo.findMember(tenant.org.id, tenant.userIds.member);
    if (!admin || !member) throw new Error("fixture member missing");

    const demoted = await memberService.updateMemberRole(tenant.actors.owner, {
      orgId: tenant.org.id,
      memberId: admin.id,
      role: "member",
    });
    expect(demoted.role).toBe("member");

    const released = await memberService.updateMemberRole(tenant.actors.owner, {
      orgId: tenant.org.id,
      memberId: member.id,
      role: "viewer",
    });
    expect(released.role).toBe("viewer");
  });

  // Incremental seat deltas stay aligned with a full recount.
  it("adjusts stored seats so a recount still agrees", async () => {
    const tenant = await createTenant("member-seat-counter", "growth");
    const off = registerUsageListeners();
    try {
      expect((await usageRepo.recomputeUsage(tenant.org.id)).seatsUsed).toBe(3);

      const viewer = await memberRepo.findMember(
        tenant.org.id,
        tenant.userIds.viewer,
      );
      const member = await memberRepo.findMember(
        tenant.org.id,
        tenant.userIds.member,
      );
      if (!viewer || !member) throw new Error("fixture member missing");

      await memberService.updateMemberRole(tenant.actors.owner, {
        orgId: tenant.org.id,
        memberId: viewer.id,
        role: "member",
      });
      expect((await usageRepo.getUsage(tenant.org.id)).seatsUsed).toBe(4);
      expect((await usageRepo.recomputeUsage(tenant.org.id)).seatsUsed).toBe(4);

      await memberService.updateMemberRole(tenant.actors.owner, {
        orgId: tenant.org.id,
        memberId: viewer.id,
        role: "viewer",
      });
      expect((await usageRepo.getUsage(tenant.org.id)).seatsUsed).toBe(3);

      await memberService.removeMember(tenant.actors.owner, {
        orgId: tenant.org.id,
        memberId: member.id,
      });
      expect((await usageRepo.getUsage(tenant.org.id)).seatsUsed).toBe(2);
      expect((await usageRepo.recomputeUsage(tenant.org.id)).seatsUsed).toBe(2);

      await memberService.removeMember(tenant.actors.owner, {
        orgId: tenant.org.id,
        memberId: viewer.id,
      });
      expect((await usageRepo.getUsage(tenant.org.id)).seatsUsed).toBe(2);
      expect((await usageRepo.recomputeUsage(tenant.org.id)).seatsUsed).toBe(2);
    } finally {
      off();
    }
  });
});

