// Joining moves the stored seat counter only for a billable role.
it("counts a joined member and not a joined viewer", async () => {
  const tenant = await createTenant("invite-join-seats", "growth");
  const off = registerUsageListeners();
  try {
    expect((await usageRepo.recomputeUsage(tenant.org.id)).seatsUsed).toBe(3);

    const viewerToken = "d".repeat(32);
    await invitationRepo.insertInvitation(
      tenant.org.id,
      {
        orgId: tenant.org.id,
        email: "joined-viewer@invite-join-seats.test",
        role: "viewer",
        expiresInDays: 14,
      },
      tenant.userIds.admin,
      hashToken(viewerToken),
    );
    const viewerUser = await userRepo.insertUser({
      email: "joined-viewer@invite-join-seats.test",
      name: "Joined Viewer",
      passwordHash: "seed",
    });
    await invitationService.acceptInvitation(viewerUser.id, { token: viewerToken });
    expect((await usageRepo.getUsage(tenant.org.id)).seatsUsed).toBe(3);

    const memberToken = "e".repeat(32);
    await invitationRepo.insertInvitation(
      tenant.org.id,
      {
        orgId: tenant.org.id,
        email: "joined-member@invite-join-seats.test",
        role: "member",
        expiresInDays: 14,
      },
      tenant.userIds.admin,
      hashToken(memberToken),
    );
    const memberUser = await userRepo.insertUser({
      email: "joined-member@invite-join-seats.test",
      name: "Joined Member",
      passwordHash: "seed",
    });
    await invitationService.acceptInvitation(memberUser.id, { token: memberToken });
    expect((await usageRepo.getUsage(tenant.org.id)).seatsUsed).toBe(4);
    expect((await usageRepo.recomputeUsage(tenant.org.id)).seatsUsed).toBe(4);
  } finally {
    off();
  }
});

// A pending billable invite holds a seat; a pending viewer invite does not.
it("counts pending billable invites, not pending viewer invites, against the quota", async () => {
  const tenant = await createTenant("invite-pending-seats", "free");

  await invitationService.inviteMember(tenant.actors.admin, {
    orgId: tenant.org.id,
    email: "pending-viewer@invite-pending-seats.test",
    role: "viewer",
  });

  await expect(
    invitationService.inviteMember(tenant.actors.admin, {
      orgId: tenant.org.id,
      email: "pending-member@invite-pending-seats.test",
      role: "member",
    }),
  ).rejects.toThrow(/seats/);
});

