input.new_string:
// Pending viewer invites do not consume the seats a later billable invite needs.
it("does not count pending viewer invites against the seat quota", async () => {
  const tenant = await createTenant("invite-pending-viewers", "starter");

  await invitationService.inviteMembers(tenant.actors.admin, {
    orgId: tenant.org.id,
    invites: Array.from({ length: 7 }, (_, index) => ({
      email: `pending-viewer-${index}@invite-pending-viewers.test`,
      role: "viewer" as const,
    })),
  });

  await expect(
    invitationService.inviteMember(tenant.actors.admin, {
      orgId: tenant.org.id,
      email: "still-fits@invite-pending-viewers.test",
      role: "member",
    }),
  ).resolves.toMatchObject({ role: "member" });
});

// Pending billable invites hold a seat, so they can fill the plan on their own.
it("counts pending billable invites against the seat quota", async () => {
  const tenant = await createTenant("invite-pending-billable", "starter");

  await invitationService.inviteMembers(tenant.actors.admin, {
    orgId: tenant.org.id,
    invites: Array.from({ length: 7 }, (_, index) => ({
      email: `pending-member-${index}@invite-pending-billable.test`,
      role: "member" as const,
    })),
  });

  await expect(
    invitationService.inviteMember(tenant.actors.admin, {
      orgId: tenant.org.id,
      email: "one-too-many@invite-pending-billable.test",
      role: "member",
    }),
  ).rejects.toThrow(/seats/);

  await expect(
    invitationService.inviteMember(tenant.actors.admin, {
      orgId: tenant.org.id,
      email: "viewer-still-ok@invite-pending-billable.test",
      role: "viewer",
    }),
  ).resolves.toMatchObject({ role: "viewer" });
});

