// A pending billable invite occupies a seat the same way an active member does.
it("refuses a viewer promotion when pending invites already fill the plan", async () => {
  const tenant = await createTenant("member-seat-pending", "starter");
  const target = await memberRepo.findMember(tenant.org.id, tenant.userIds.viewer);
  if (!target) throw new Error("fixture viewer missing");

  for (let index = 0; index < 7; index += 1) {
    await invitationRepo.insertInvitation(
      tenant.org.id,
      {
        orgId: tenant.org.id,
        email: `held-${index}@member-seat-pending.test`,
        role: "member",
        expiresInDays: 14,
      },
      tenant.userIds.owner,
      `pending-token-${index}`,
    );
  }

  await expect(
    memberService.updateMemberRole(tenant.actors.owner, {
      orgId: tenant.org.id,
      memberId: target.id,
      role: "admin",
    }),
  ).rejects.toThrow(/seats/);

  const after = await memberRepo.findMember(tenant.org.id, tenant.userIds.viewer);
  expect(after?.role).toBe("viewer");
});

